import app from 'flarum/forum/app';
import ComposePollPage from '../components/ComposePollPage';
import PollsPage from '../components/PollsPage';
import ItemList from 'flarum/common/utils/ItemList';
import Separator from 'flarum/common/components/Separator';
import Button from 'flarum/common/components/Button';

/**
 * The `UserControls` utility constructs a list of buttons for a user which
 * perform actions on it.
 */
export default {
  /**
   * Get a list of controls for a user.
   */
  controls(poll, context) {
    const items = new ItemList();
    const sections = ['poll', 'moderation', 'destructive'];
    sections.forEach(section => {
      const controls = this["".concat(section, "Controls")](poll, context).toArray();
      if (controls.length) {
        controls.forEach(item => items.add(item.itemName, item));
        items.add(section + 'Separator', m(Separator, null));
      }
    });
    return items;
  },
  /**
   * Get controls for direct modifcation actions on polls (e.g. vote, view voters).
   */
  pollControls(poll, context) {
    const items = new ItemList();
    return items;
  },
  /**
   * Get controls for a user pertaining to moderation (e.g. suspend, edit).
   */
  moderationControls(poll, context) {
    const items = new ItemList();
    if (poll.canEdit()) {
      items.add('edit', m(Button, {
        icon: "fas fa-pencil-alt",
        onclick: this.editAction.bind(this, poll)
      }, app.translator.trans("fof-polls.forum.poll_controls.edit_label")));
    }
    return items;
  },
  /**
   * Get controls for a user which are destructive (e.g. delete).
   * @protected
   */
  destructiveControls(poll, context) {
    const items = new ItemList();
    if (poll.canDelete()) {
      items.add('delete', m(Button, {
        icon: "far fa-trash-alt",
        onclick: this.deleteAction.bind(this, poll)
      }, app.translator.trans("fof-polls.forum.poll_controls.delete_label")));
    }
    return items;
  },
  /**
   * Delete the poll.
   */
  async deleteAction(poll) {
    if (!confirm(app.translator.trans("fof-polls.forum.poll_controls.delete_confirmation"))) {
      return;
    }
    return poll.delete().then(() => {
      this.showDeletionAlert(poll, 'success');
      if (app.current.matches(ComposePollPage, {
        id: poll.id()
      }) || app.current.matches(PollsPage, {
        id: poll.id()
      })) {
        app.history.back();
      } else {
        window.location.reload();
      }
    }).catch(() => this.showDeletionAlert(poll, 'error'));
  },
  /**
   * Show deletion alert of poll
   */
  showDeletionAlert(poll, type) {
    const message = {
      success: "fof-polls.forum.poll_controls.delete_success_message",
      error: "fof-polls.forum.poll_controls.delete_error_message"
    }[type];
    app.alerts.show({
      type
    }, app.translator.trans(message, {
      poll: poll
    }));
  },
  /**
   * Edit the poll.
   */
  editAction(poll) {
    m.route.set(app.route('fof.polls.composer', {
      id: poll.id()
    }));
  }
};